-- Disposable fixture only; all imported rows and retry ledgers are rolled back.
begin;
create temporary table bulk_plans(name text primary key,kind text,plan jsonb);
grant select,insert,update on bulk_plans to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
insert into bulk_plans values('equipment','equipment',public.preview_import_table('00000000-0000-0000-0000-000000000001','equipment',
 '[{"code":"BULK_TEST","name":"Thiết bị thử","category":"SPREADER_AUTO","base_status":"stopped","serial":null,"year":null,"aliases":[],"notes":""}]'));
select test.ok((select plan->0->>'action'='add' from bulk_plans where name='equipment'),'preview marks new code');
select test.ok(not exists(select 1 from public.equipment where code='BULK_TEST'),'preview writes no equipment');
select test.ok(public.import_table_batch('00000000-0000-0000-0000-000000000001','equipment','add',(select plan from bulk_plans where name='equipment'),'72000000-0000-0000-0000-000000000001')=1,'leader imports catalog without hours');
select test.ok((select initial_hours is null and accumulated_hours is null from public.equipment where code='BULK_TEST'),'bulk catalog preserves unknown baseline');
select test.ok(public.import_table_batch('00000000-0000-0000-0000-000000000001','equipment','add',(select plan from bulk_plans where name='equipment'),'72000000-0000-0000-0000-000000000001')=1,'retry returns same count after successful import');
select test.ok((select count(*)=1 from public.equipment where code='BULK_TEST'),'retry creates no duplicate equipment');
select test.fails($q$select public.import_table_batch('00000000-0000-0000-0000-000000000001','equipment','replace',(select plan from bulk_plans where name='equipment'),'72000000-0000-0000-0000-000000000001')$q$,'22023','same key cannot change import mode');
insert into bulk_plans values('eq_stale','equipment',public.preview_import_table('00000000-0000-0000-0000-000000000001','equipment',
 '[{"code":"BULK_TEST","name":"Tên từ tệp","category":"SPREADER_AUTO","base_status":"stopped","serial":null,"year":null,"aliases":[],"notes":""}]'));
update public.equipment set name='Tên sửa sau xem trước' where code='BULK_TEST';
select test.fails($q$select public.import_table_batch('00000000-0000-0000-0000-000000000001','equipment','replace',(select plan from bulk_plans where name='eq_stale'),gen_random_uuid())$q$,'40001','stale catalog preview cannot overwrite metadata');
select test.fails($q$select public.preview_import_table('00000000-0000-0000-0000-000000000001','materials','[{"code":"M","name":"Thử","unit":"bộ","stock":100}]')$q$,'22023','unknown stock field rejected');
insert into bulk_plans values('materials','materials',public.preview_import_table('00000000-0000-0000-0000-000000000001','materials','[{"code":"BULK_MAT","name":"Vật tư thử","unit":"bộ"}]'));
select test.ok(public.import_table_batch('00000000-0000-0000-0000-000000000001','materials','add',(select plan from bulk_plans where name='materials'),'72000000-0000-0000-0000-000000000002')=1,'material catalogue import creates no stock movement');
select test.ok((select service_limit_hours is null and minimum_stock=0 from public.materials where code='BULK_MAT'),'material import does not invent service limit or opening inventory');
select test.fails($q$select public.preview_import_table('00000000-0000-0000-0000-000000000001','materials','[{"code":"BULK_MAT","name":"Thử","unit":"chiếc"}]')$q$,'22023','existing material unit cannot change');
insert into bulk_plans values('cargo','cargo',public.preview_import_table('00000000-0000-0000-0000-000000000001','cargo','[{"code":"BULK_CARGO","name":"Hàng thử","unit":"TONNE"}]'));
select test.ok(public.import_table_batch('00000000-0000-0000-0000-000000000001','cargo','add',(select plan from bulk_plans where name='cargo'),'72000000-0000-0000-0000-000000000003')=1,'cargo catalogue establishes explicit allowed unit');
select test.fails($q$select public.preview_import_table('00000000-0000-0000-0000-000000000001','cargo','[{"code":"BULK_CARGO","name":"Hàng thử","unit":"M3"}]')$q$,'22023','existing cargo unit cannot change');
insert into bulk_plans values('hours','hours',public.preview_import_table('00000000-0000-0000-0000-000000000001','hours','[{"equipment_code":"BULK_TEST","month":"2026-09-01","operating_hours":100}]'));
select test.ok(public.import_table_batch('00000000-0000-0000-0000-000000000001','hours','add',(select plan from bulk_plans where name='hours'),'72000000-0000-0000-0000-000000000004')=1,'monthly hours import independent of catalogue baseline');
select test.ok(public.import_table_batch('00000000-0000-0000-0000-000000000001','hours','add',(select plan from bulk_plans where name='hours'),'72000000-0000-0000-0000-000000000004')=1,'monthly retry is safe after snapshot changed');
select public.confirm_operating_baseline((select id from public.equipment where code='BULK_TEST'),10,'2026-09-01',gen_random_uuid());
insert into bulk_plans values('hours_update','hours',public.preview_import_table('00000000-0000-0000-0000-000000000001','hours','[{"equipment_code":"BULK_TEST","month":"2026-09-01","operating_hours":90}]'));
select test.fails($q$select public.import_table_batch('00000000-0000-0000-0000-000000000001','hours','add',(select plan from bulk_plans where name='hours_update'),gen_random_uuid())$q$,'22023','add-only mode never replaces an existing monthly row');
select test.ok(public.import_table_batch('00000000-0000-0000-0000-000000000001','hours','replace',(select plan from bulk_plans where name='hours_update'),'72000000-0000-0000-0000-000000000005')=1,'explicit replace mode changes monthly value');
select test.ok((select accumulated_hours=100 from public.equipment where code='BULK_TEST'),'hours correction uses delta once');
select test.fails($q$select public.import_table_batch('00000000-0000-0000-0000-000000000001','hours','replace',(select plan from bulk_plans where name='hours_update'),gen_random_uuid())$q$,'40001','changed month rejects stale preview');
select test.fails($q$select public.preview_import_table('00000000-0000-0000-0000-000000000001','hours','[{"equipment_code":"BULK_TEST","month":"2026-08-01","operating_hours":0}]')$q$,'22023','pre-baseline month rejected');
select test.fails($q$select public.preview_import_table('00000000-0000-0000-0000-000000000001','hours','[{"equipment_code":"BULK_TEST","month":"2026-10-01","operating_hours":900}]')$q$,'22023','hours cannot exceed calendar time');
select test.fails($q$select public.import_table_batch('00000000-0000-0000-0000-000000000001','equipment','add',
 '[{"row":{"code":"BULK_ROLLBACK","name":"Thử","category":"QC","base_status":"available","serial":null,"year":null,"aliases":[],"notes":""},"expected":null},{"row":{"code":"BAD","name":"Thử","category":"WRONG","base_status":"available","serial":null,"year":null,"aliases":[],"notes":""},"expected":null}]',gen_random_uuid())$q$,'22023','one bad row aborts entire batch');
select test.ok(not exists(select 1 from public.equipment where code='BULK_ROLLBACK'),'failed batch creates no partial row');
insert into bulk_plans values('container','container',public.preview_import_table('00000000-0000-0000-0000-000000000001','container','[{"equipment_code":"BULK_TEST","month":"2026-09-01","boxes":3382}]'));
select test.ok(public.import_table_batch('00000000-0000-0000-0000-000000000001','container','add',(select plan from bulk_plans where name='container'),'72000000-0000-0000-0000-000000000006')=1,'container count stored as pieces only');
insert into bulk_plans values('other','other',public.preview_import_table('00000000-0000-0000-0000-000000000001','other','[{"equipment_code":"BULK_TEST","month":"2026-09-01","cargo_code":"BULK_CARGO","quantity":12.125}]'));
select test.ok(public.import_table_batch('00000000-0000-0000-0000-000000000001','other','add',(select plan from bulk_plans where name='other'),'72000000-0000-0000-0000-000000000007')=1,'other cargo stored with registered unit');
select test.ok((select accumulated_hours=100 from public.equipment where code='BULK_TEST'),'container and other cargo imports never modify running hours');
select test.fails($q$select public.preview_import_table('00000000-0000-0000-0000-000000000001','hours','[{"equipment_code":"BULK_TEST","month":"2026-09-01","operating_hours":1},{"equipment_code":"BULK_TEST","month":"2026-09-01","operating_hours":2}]')$q$,'22023','duplicate month keys rejected, not summed');
select test.fails($q$select * from private.bulk_table_requests$q$,'42501','internal retry ledger is inaccessible to clients');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',true);
select test.fails($q$select public.preview_import_table('00000000-0000-0000-0000-000000000001','hours','[{"equipment_code":"BULK_TEST","month":"2026-09-01","operating_hours":1}]')$q$,'42501','supply role cannot import hours');
select test.ok(jsonb_array_length(public.preview_import_table('00000000-0000-0000-0000-000000000001','materials','[{"code":"BULK_MAT2","name":"Thử","unit":"bộ"}]'))=1,'supply role can prepare material catalogue import');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
select test.fails($q$select public.preview_import_table('00000000-0000-0000-0000-000000000001','materials','[{"code":"M","name":"Thử","unit":"bộ"}]')$q$,'42501','technician cannot import catalogue');
select test.ok(jsonb_array_length(public.preview_import_table('00000000-0000-0000-0000-000000000001','hours','[{"equipment_code":"BULK_TEST","month":"2026-09-01","operating_hours":1}]'))=1,'technician can prepare monthly hours import');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000005',true);
select test.fails($q$select public.import_table_batch('00000000-0000-0000-0000-000000000001','equipment','add',(select plan from bulk_plans where name='equipment'),gen_random_uuid())$q$,'42501','foreign workspace leader cannot import');
set local role anon;
select test.fails($q$select public.preview_import_table('00000000-0000-0000-0000-000000000001','equipment','[]')$q$,'42501','anonymous cannot preview private data');
select test.fails($q$select public.import_table_batch('00000000-0000-0000-0000-000000000001','equipment','add','[]',gen_random_uuid())$q$,'42501','anonymous cannot import');
reset role;
select test.ok((select count(*)=2 from pg_proc where oid in ('public.preview_import_table(uuid,text,jsonb)'::regprocedure,'public.import_table_batch(uuid,text,text,jsonb,uuid)'::regprocedure) and not prosecdef),'public bulk APIs never bypass RLS');
rollback;
